import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    start_time = time.time()
    end_time = start_time + duration
    log_data = []
    system = platform.system()
    while time.time() < end_time:
        timestamp = time.time()
        cpu_usage = 0.0
        try:
            if system == 'Windows':
                output = subprocess.check_output(['wmic', 'cpu', 'get', 'loadpercentage'])
                lines = output.decode().splitlines()
                for line in lines:
                    line = line.strip()
                    if line and 'LoadPercentage' not in line:
                        cpu_usage = float(line)
                        break
            else:
                output = subprocess.check_output(['top', '-bn1'])
                lines = output.decode().splitlines()
                for line in lines:
                    if 'Cpu(s)' in line:
                        parts = line.split(',')
                        for part in parts:
                            if 'us' in part:
                                cpu_usage = float(part.split()[0].replace('%', ''))
                                break
                        break
        except Exception:
            cpu_usage = 0.0
        log_data.append({'timestamp': timestamp, 'cpu_usage': cpu_usage})
        if time.time() + interval >= end_time:
            break
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(log_data, f)
        return LOGFILE_PATH
    except IOError:
        return None

import subprocess
import psutil
import time
def task_func(process_name: str) -> str:
    process_found = False
    for proc in psutil.process_iter():
        try:
            if proc.name() == process_name:
                process_found = True
                proc.terminate()
        except Exception:
            pass

    time.sleep(1)

    is_process_name_verified = len(process_name) > 0
    subprocess.Popen(process_name, shell=is_process_name_verified)

    if process_found:
        return f"Process found. Restarting {process_name}."
    else:
        return f"Process not found. Starting {process_name}."

